CREATE TABLE IF NOT EXISTS profiles(id BIGSERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,display_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS watchlist(email TEXT NOT NULL,title_id BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(email,title_id));
CREATE TABLE IF NOT EXISTS progress(email TEXT NOT NULL,title_id BIGINT NOT NULL,seconds DOUBLE PRECISION NOT NULL CHECK(seconds>=0),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(email,title_id));
